fn take(b: Box<Vec<u32>>) -> usize {
    let v = *b;
    let n = b.len() + v.len();
    n
}

fn append_len(v: &mut Vec<usize>) {
    v.push(v.pop().unwrap());
}

fn mirror(q: &mut Vec<u64>) {
    let ids = q.iter().copied();
    q.extend(ids);
}

fn send(o: &mut Vec<Vec<u8>>, b: Vec<u8>) {
    let n = &b[0];
    o.push(b);
    println!("{n:?}");
}

fn reset(q: &mut Vec<u32>) {
    let head = q.first();
    *q = Vec::new();
    println!("{head:?}");
}

fn index(ids: Vec<String>) -> usize {
    let mut ix: Vec<&str> = vec![];
    for id in ids {
        ix.push(&id);
    }
    ix.len()
}

fn label(id: u32) -> usize {
    let tag = id.to_string().trim();
    let tag = tag.trim();
    tag.len() + 1
}

use std::cell::RefCell;

fn main() {
    let q = RefCell::new(vec![1, 2, 3]);
    let n = q.borrow().len();
    for i in 0..n {
        if let 2 = q.borrow()[i] {
            q.borrow_mut().push(4);
        }
    }
    println!("{}", q.borrow().len());
}

struct Lexer(&str);

fn count(t: String) -> usize {
    let lx = Lexer(&t);
    lx.0.len()
}

fn above(
    v: &[u32],
    min: u32,
) -> impl Iterator<Item = &u32> {
    v.iter().filter(|x| **x > min)
}

fn warm(n: usize) -> Vec<u32> {
    let ids: Vec<u32>;
    match n {
        0 => ids = Vec::new(),
        _ => {}
    }
    ids
}

type V = Vec<u32>;
fn rotate(cur: V, next: V) -> V {
    let old = cur;
    cur = next;
    old
}

fn tick(n: &mut u32) -> u32 {
    let m = &mut *n;
    *m += 1;
    *n + *m
}

fn take(b: &Box<Vec<u32>>) -> usize {
    let v = *b;
    let n = v.len();
    n
}

fn pair(ns: [String; 2]) -> usize {
    let a = ns[0];
    let b = &ns[1];
    a.len() + b.len()
}

struct Conn {
    addr: String,
    open: bool,
}

impl Drop for Conn {
    fn drop(&mut self) {
        self.open = false;
    }
}

fn addr_of(mut c: Conn) -> String {
    c.addr
}

struct View<'a> {
    bytes: &'a [u8],
}

fn view(pool: &[u8]) -> View<'_> {
    let head = pool[..4].to_vec();
    View { bytes: &head }
}

fn spawn_worker(id: &u32) {
    let name = format!("worker-{id}");
    let h = std::thread::spawn(move || {
        println!("{name} {id}");
    });
    h.join().unwrap();
    println!("{id} done");
}

struct Table {
    blocks: Vec<u32>,
    epoch: u64,
}

impl Table {
    fn flush(&self) -> Vec<u32> {
        self.epoch += 1;
        std::mem::take(&mut self.blocks)
    }
}

struct Table { ids: Vec<u32> }

fn swap_ids(a: &mut Table, b: &Table) {
    std::mem::swap(&mut a.ids, &mut b.ids);
}

use std::cell::RefCell;

fn main() {
    let q = RefCell::new(vec![1, 2]);
    let n = q.borrow().len();
    q.borrow_mut().push(q.borrow().len());
    println!("{:?}", q.borrow());
}
